async function importAll() {
  console.log(`Importing ${updates.length} updates...`);
  let count = 0;
  for (const update of updates) {
    const { id, ...data } = update;
    await setDoc(doc(db, "updates", id), data);
    count++;
    if (count % 50 === 0) console.log(`${count}/${updates.length} done`);
  }
  console.log("Done!");
  process.exit(0);
}

